"""Read retained test order; all UI mutation checks use intercepted fictitious shipments."""
import copy
import json
from pathlib import Path
from playwright.sync_api import sync_playwright, expect
from verify_goods_workspace_ui import login, request, BASE


def main():
    root=Path(__file__).resolve().parents[2];case={'shipment_id':3,'shipment_sn':'XS870a08cfdade45b5be4ad60d3cc802ab','shipment_url':BASE+'/oms-order/shipments?number=XS870a08cfdade45b5be4ad60d3cc802ab'};output=root/'outputs/package-ui';output.mkdir(parents=True,exist_ok=True);token=login()
    try:
        live=request('/order/orders/shipments/'+str(case['shipment_id']),token=token)['data'];assert live['shipped_quantity']==6 and live['packaged_quantity']==6 and live['unpacked_quantity']==0 and len(live['packages'])==1 and len(live['outbound_records'])==1
        source=copy.deepcopy(live);source.update(id=9999999101,shipment_sn='FH_PACKAGE_UI',order_sn='SO_PACKAGE_UI',order_id=9999999100,quantity=8,shipped_quantity=4,packaged_quantity=0,unpacked_quantity=4,package_count=0,status='PART_SHIPPED',control_version=1,can_register_package=True,can_reconcile_receipts=False,can_match_carrier=False,can_virtual_outbound=True,virtual_outbound_state='COMPLETED',wms_dispatch_state='NONE',can_dispatch=False,can_query_warehouse=False,can_query_virtual_outbound=False,logs=[],packages=[])
        source['lines']=[dict(id=9999999111,allocation_id=9999999112,sku_sn='UI_SKU',goods_name='UI 商品',platform_oid='999999910001',store_code='UI_V1',batch_id=1,quantity=8,shipped_quantity=4,packaged_quantity=0,source_type='PUBLIC_EXTRA')]
        source['outbound_records']=[dict(id=1,source_mode='VIRTUAL',quantity=4,state='COMPLETED',outbound_time='2026-10-12 12:00:00',created_by='UI 验收',lines=[dict(id=9999999111,sku_sn='UI_SKU',platform_oid='999999910001',store_code='UI_V1',batch_id=1,quantity=4)])]
        wms=copy.deepcopy(source);wms.update(id=9999999201,shipment_sn='FH_RECEIPT_UI',outbound_mode=1,shipped_quantity=0,packaged_quantity=0,unpacked_quantity=0,status='WAREHOUSE_PROCESSING',can_register_package=False,can_virtual_outbound=False,virtual_outbound_state='NONE',wms_dispatch_state='ACCEPTED',can_reconcile_receipts=True,outbound_unconfirmed_count=1,packages=[])
        wms['lines'][0].update(id=9999999211,shipped_quantity=0);wms['outbound_records']=[dict(id=2,source_mode='WMS',quantity=4,state='FAILED',message_id='UI_MESSAGE',last_error='来源余额异常，请核对原回传',created_by='UI 仓库',lines=[])]
        captured=[]
        def fulfill(route,data):route.fulfill(status=200,content_type='application/json',body=json.dumps(data,ensure_ascii=False))
        def register(route):
            body=route.request.post_data_json;captured.append(('package',body));assert body['control_version']==source['control_version'] and len(body['request_id'])>=16 and body['express_code']=='TEST-UI-WAYBILL' and body['lines']==[{'id':9999999111,'quantity':2}]
            source.update(packaged_quantity=2,unpacked_quantity=2,package_count=1,control_version=2);source['lines'][0]['packaged_quantity']=2;source['packages']=[dict(id=9999999151,package_code='UI_PKG',express_code=body['express_code'],carrier_code='SF',carrier_name=source['carrier_name'],source_mode='VIRTUAL',quantity=2,outbound_time='2026-10-12 12:10:00',lines=[dict(shipment_line_id=9999999111,sku_sn='UI_SKU',goods_name='UI 商品',platform_oid='999999910001',quantity=2)])]
            fulfill(route,{'code':200,'data':dict(id=9999999151,success=True,message='运单已登记，库存保持不变')})
        def reconcile(route):
            captured.append(('reconcile',wms['id']));wms.update(shipped_quantity=4,packaged_quantity=4,package_count=1,status='PART_SHIPPED',outbound_unconfirmed_count=0,control_version=2);wms['outbound_records'][0].update(state='COMPLETED',last_error='',lines=[dict(id=9999999211,sku_sn='UI_SKU',quantity=4)]);wms['packages']=[dict(id=9999999251,package_code='WMS_PKG',express_code='TEST-WMS-UI',carrier_code='SF',carrier_name=wms['carrier_name'],source_mode='WMS',quantity=4,lines=[dict(shipment_line_id=9999999211,sku_sn='UI_SKU',goods_name='UI 商品',platform_oid='999999910001',quantity=4)])];wms['lines'][0].update(shipped_quantity=4,packaged_quantity=4)
            fulfill(route,{'code':200,'data':[dict(id=2,success=True,state='COMPLETED',message='出库回传已确认，库存、发货数量和包裹已更新')]})
        with sync_playwright() as p:
            browser=p.chromium.launch(headless=True);context=browser.new_context(viewport={'width':1600,'height':1100});context.add_cookies([{'name':'Admin-Token','value':token,'url':BASE}]);page=context.new_page();errors=[];page.on('pageerror',lambda e:errors.append(str(e)))
            page.goto(case['shipment_url'],wait_until='networkidle');page.get_by_role('button',name=case['shipment_sn'],exact=True).first.click();drawer=page.locator('.shipment-detail:visible');history=drawer.locator('.outbound-history');cards=drawer.locator('.shipment-package-cards');expect(cards).to_contain_text('TEST-SF-');history.scroll_into_view_if_needed();page.screenshot(path=str(output/'retained-test-packages.png'),full_page=True,animations='disabled');drawer.get_by_role('button',name='关闭',exact=True).click();expect(drawer).not_to_be_visible()
            page.route('**/order/orders/shipments/list?*',lambda r:fulfill(r,{'code':200,'rows':[source,wms],'total':2}));page.route('**/order/orders/shipments/9999999101',lambda r:fulfill(r,{'code':200,'data':source}));page.route('**/order/orders/shipments/9999999201',lambda r:fulfill(r,{'code':200,'data':wms}));page.route('**/order/orders/shipments/9999999101/packages',register);page.route('**/order/orders/shipments/9999999201/reconcile-receipts',reconcile)
            page.goto(BASE+'/oms-order/shipments?number=UI_PACKAGE',wait_until='networkidle');page.get_by_role('button',name='FH_PACKAGE_UI',exact=True).first.click();drawer=page.locator('.shipment-detail:visible');history=drawer.locator('.outbound-history');cards=drawer.locator('.shipment-package-cards');cards.get_by_role('button',name='登记运单',exact=True).click();dialog=page.locator('.el-dialog:visible');dialog.get_by_placeholder('快递实际运单号',exact=True).fill('TEST-UI-WAYBILL');dialog.locator('.el-input-number input').fill('2');dialog.locator('.el-input-number input').blur();dialog.get_by_role('button',name='登记运单（2 件）',exact=True).click();expect(dialog).to_contain_text('库存保持不变');dialog.get_by_role('button',name='关闭',exact=True).click();expect(dialog).not_to_be_visible();expect(cards).to_contain_text('TEST-UI-WAYBILL');expect(cards).to_contain_text('已出库待关联包裹 2 件');assert source['shipped_quantity']==4;cards.locator('.package-sources .el-collapse-item__header').first.click();expect(cards).to_contain_text('999999910001');cards.scroll_into_view_if_needed();page.screenshot(path=str(output/'manual-package-fixture.png'),full_page=True,animations='disabled');drawer.get_by_role('button',name='关闭',exact=True).click();expect(drawer).not_to_be_visible()
            page.get_by_role('button',name='FH_RECEIPT_UI',exact=True).first.click();drawer=page.locator('.shipment-detail:visible');history=drawer.locator('.outbound-history');cards=drawer.locator('.shipment-package-cards');expect(cards.get_by_role('button',name='登记运单',exact=True)).to_have_count(0);expect(history).to_contain_text('记账失败');history.get_by_role('button',name='核对出库回传',exact=True).click();expect(history).to_contain_text('出库回传已确认');expect(cards).to_contain_text('TEST-WMS-UI');expect(history).to_contain_text('已记账');history.scroll_into_view_if_needed();page.screenshot(path=str(output/'wms-receipt-fixture.png'),full_page=True,animations='disabled');assert len(captured)==2 and not errors,(captured,errors);browser.close()
        print(json.dumps({'retained_live_test':'passed','manual_parcel_quantity_and_history':'passed','wms_receipt_retry_and_parcels':'passed','real_mutations_in_ui_fixtures':0},ensure_ascii=False))
    finally:request('/auth/logout',token=token,method='DELETE')


if __name__=='__main__':main()
